using System.Text;using System.Text.Json;namespace QuantForge.Core;public sealed class AndroidResearchReadinessCardFileStore{private readonly string _path;public AndroidResearchReadinessCardFileStore(string path)=>_path=Path.GetFullPath(path);public void Save(AndroidResearchReadinessCard value){if(value.CanSubmitOrders)throw new InvalidOperationException("Readiness card cannot grant order authority.");Directory.CreateDirectory(Path.GetDirectoryName(_path)!);File.WriteAllText(_path,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}),new UTF8Encoding(false));}public AndroidResearchReadinessCard Load(){var v=JsonSerializer.Deserialize<AndroidResearchReadinessCard>(File.ReadAllText(_path))??throw new InvalidOperationException("Readiness card JSON is invalid.");if(v.CanSubmitOrders)throw new InvalidOperationException("Persisted readiness card grants order authority.");return v;}}
